// 增量接口：已知答案，覆盖空输入、文本、二进制、分组与填充边界。
void test_known_answers() {
    CHECK_EQ(hex_one_shot(Bytes{}), kHexEmpty);
    CHECK_EQ(hex_one_shot(to_bytes("abc")), kHexAbc);
    CHECK_EQ(hex_one_shot(to_bytes(
